using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options backed by a source-gen context that only knows about "Person".
var options = new JsonSerializerOptions { TypeInfoResolver = AppJsonContext.Default };

// ── 1. Strongly-typed retrieval ──────────────────────────────────────
// GetTypeInfo<T>() returns JsonTypeInfo<T> directly — no cast needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Sample serialize: {JsonSerializer.Serialize(new Person("Ada", 36), personInfo)}");

// ── 2. Probe without throwing ────────────────────────────────────────
// TryGetTypeInfo returns false instead of throwing when the resolver
// can't produce metadata for the requested type.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"Person metadata found  → {found!.Type.Name}");
else
    Console.WriteLine("Person metadata NOT found");

if (options.TryGetTypeInfo(typeof(Order), out _))
    Console.WriteLine("Order  metadata found");
else
    Console.WriteLine("Order  metadata NOT found (resolver doesn't cover it)");

// Models
public record Person(string Name, int Age);
public record Order(int Id, decimal Total);   // deliberately NOT in the context

// Source-gen context — only Person is included.
[JsonSerializable(typeof(Person))]
partial class AppJsonContext : JsonSerializerContext;

